{"command":"cd /tmp/<path> && python3 - <<'EOF'
import random
from duration import parse_duration

alphabet = "0123456789wdhms:. -+H"
random.seed(0)
for _ in range(50000):
    s = "".join(random.choice(alphabet) for _ in range(random.randint(0, 12)))
    try:
        parse_duration(s)
    except ValueError:
        pass
    except Exception as exc:
        raise AssertionError((s, type(exc).__name__, exc))

assert parse_duration("0.01h") == 36
assert parse_duration("0.001h".replace("001", "002")) == 7  # 0.002h = 7.2 invalid
EOF"}
